<?php use App\Helpers\{View,Csrf};?><section class="detail"><div class="detail-image"><?php if($product['image']):?><img src="<?=View::e($product['image'])?>" alt="<?=View::e($product['name'])?>"><?php else:?><span>🎂</span><?php endif;?></div><div><span class="eyebrow"><?=View::e($product['category_name'])?></span><h1><?=View::e($product['name'])?></h1><div class="price">$<?=number_format($product['price'],2)?></div><p class="lead"><?=nl2br(View::e($product['description']))?></p><p><b>Disponibles:</b> <?=$product['stock']?> · <b>Ganas:</b> ⭐ <?=$product['display_points']?> puntos por unidad</p><form class="buyrow" method="post" action="/cart/add"><?=Csrf::field()?><input type="hidden" name="product_id" value="<?=$product['id']?>"><input type="number" name="quantity" min="1" max="<?=$product['stock']?>" value="1"><button class="primary">Agregar al carrito</button></form></div></section>